output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "Customers are obliged to take the available entrance cart before shopping, rather than starting the trip empty-handed.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_rack": "at(1,5)",
        "has_cart": "hasCart",
        "cart_waiting_at_entrance": "cartAt(1,5)"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_rack",
              "cart_waiting_at_entrance",
              "PICKUP_CART"
            ]
          },
          "post": "has_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "pickup_items_only_with_cart",
    "text": "Customers are prohibited from picking up shelf items unless they currently have a shopping cart.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "shelf_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        },
        "shelf_pickup_with_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "has_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "shelf_pickup_without_cart"
    }
  },
  {
    "id": "no_hand_carried_groceries",
    "text": "Customers are prohibited from carrying groceries loose in their hands; groceries should be transported in the cart.",
    "abstraction": {
      "state_properties": {
        "hand_carrying_item": "handFull",
        "has_cart": "hasCart"
      },
      "events": {
        "become_hand_full": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "has_cart"
              }
            ]
          },
          "post": "hand_carrying_item"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "hand_carrying_item"
    }
  },
  {
    "id": "return_cart_after_use",
    "text": "After taking a cart, a customer is obliged to return it to the designated return bay before leaving.",
    "abstraction": {
      "state_properties": {
        "at_return_bay": "at(0,1)",
        "has_cart": "hasCart",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "has_cart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "has_cart",
              "at_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "leave_cart_only_at_return_bay",
    "text": "Customers are prohibited from abandoning a cart anywhere except the designated cart return bay.",
    "abstraction": {
      "state_properties": {
        "at_return_bay": "at(0,1)",
        "has_cart": "hasCart"
      },
      "events": {
        "abandon_cart_outside_return_bay": {
          "pre": {
            "and": [
              "has_cart",
              "LEAVE_CART",
              {
                "not": "at_return_bay"
              }
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "proper_cart_return": {
          "pre": {
            "and": [
              "has_cart",
              "at_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "abandon_cart_outside_return_bay"
    }
  },
  {
    "id": "no_carts_in_pedestrian_exit_zone",
    "text": "Shopping carts are prohibited in the pedestrian-only exit zone, so customers must park the cart before walking to the exit.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "pedestrian_exit_zone": {
          "or": [
            "at(2,1)",
            "at(3,1)",
            "at(4,1)",
            "at(5,1)",
            "at(6,1)",
            "at(7,1)",
            "at(8,1)",
            "at(9,1)",
            "at(5,2)",
            "at(6,2)",
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "enter_pedestrian_exit_zone_with_cart": {
          "pre": {
            "and": [
              "MOVE",
              "has_cart"
            ]
          },
          "post": "pedestrian_exit_zone"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "has_cart",
          "pedestrian_exit_zone"
        ]
      }
    }
  },
  {
    "id": "exit_requires_returned_cart",
    "text": "A customer is prohibited from exiting unless the cart has already been parked in the return bay.",
    "abstraction": {
      "state_properties": {
        "at_exit": "at(9,5)",
        "cart_parked_in_return_bay": "cartAt(0,1)",
        "cart_not_returned": {
          "not": "cartAt(0,1)"
        }
      },
      "events": {
        "exit_store": {
          "pre": {
            "and": [
              "at_exit",
              "EXIT"
            ]
          },
          "post": null
        },
        "exit_without_returned_cart": {
          "pre": {
            "and": [
              "at_exit",
              "EXIT",
              "cart_not_returned"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_without_returned_cart"
    }
  },
  {
    "id": "no_more_interactions_after_cart_return",
    "text": "Once the cart is parked in the return bay, customers are prohibited from further object interactions and should proceed only by walking to the exit.",
    "abstraction": {
      "state_properties": {
        "cart_parked_in_return_bay": "cartAt(0,1)",
        "after_cart_return_marker": "cartAt(0,1)"
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "after_cart_return_marker",
              "INTERACT"
            ]
          },
          "post": null
        },
        "post_return_move": {
          "pre": {
            "and": [
              "after_cart_return_marker",
              "MOVE"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  }
]
